Input: {"question": "When did John Sparke die?", "source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0344-2e30be8d9090:d00", "start": 0, "end": 114, "text": "John Sparke (died 1566) John Sparke (died 1566) was an English politician who sat in the House of Commons in 1554."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0344-2e30be8d9090:d00", "start": 115, "end": 188, "text": "Sparke was originally from Nantwich, Cheshire and settled at Plympton St."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0344-2e30be8d9090:d00", "start": 189, "end": 197, "text": "Maurice."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0344-2e30be8d9090:d00", "start": 198, "end": 256, "text": "He was collector of the subsidy for Plympton Erle in 1523."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0344-2e30be8d9090:d00", "start": 257, "end": 320, "text": "In 1554, he was elected Member of Parliament for Plympton Erle."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0344-2e30be8d9090:d00", "start": 321, "end": 374, "text": "He was mayor of Plympton Erle later in the same year."}, "D1S7": {"document_number": 1, "doc_id": "ramdocs-0344-2e30be8d9090:d00", "start": 375, "end": 463, "text": "Sparke died in 1566 and was buried in the church of Plympton St Maurice on 11 July 1566."}, "D1S8": {"document_number": 1, "doc_id": "ramdocs-0344-2e30be8d9090:d00", "start": 464, "end": 517, "text": "Sparke married Jane Moore of Devon and had four sons."}, "D1S9": {"document_number": 1, "doc_id": "ramdocs-0344-2e30be8d9090:d00", "start": 518, "end": 547, "text": "She was buried on 29 December"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0344-2e30be8d9090:d01", "start": 0, "end": 208, "text": "John Sparke (died 1680) John Sparke (1636 - 8 October 1680) of the Friary, in the parish of St Jude, Plymouth, Devon, was an English landowner and politician who sat in the House of Commons from 1677 to 1680."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0344-2e30be8d9090:d01", "start": 209, "end": 433, "text": "Sparke was the son of Jonathan Sparke of Plymouth (second son of John Sparke (c 1574–1640), MP, of The Friary, in the parish of St Jude, Plymouth) by his wife Mary Basset, daughter of Sir Robert Basset of Heanton Punchardon."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0344-2e30be8d9090:d01", "start": 434, "end": 561, "text": "Jonathan Sparke is mentioned in the Travel Journal of Cosimo III de' Medici, Grand Duke of Tuscany (1642-1723) who was visiting"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0344-2e30be8d9090:d02", "start": 0, "end": 12, "text": "in Plymouth."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0344-2e30be8d9090:d02", "start": 13, "end": 84, "text": "It was then acquired by the Sparke family, who made it their residence."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0344-2e30be8d9090:d02", "start": 85, "end": 153, "text": "From Sparke it passed to the Molesworths and Clarkes to the Beweses."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0344-2e30be8d9090:d02", "start": 154, "end": 328, "text": "The buildings were converted into a hospital for soldiers in the year 1794, when a deadly sickness was ravaging the troops detained at the port for the West India expedition."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0344-2e30be8d9090:d02", "start": 329, "end": 432, "text": "They were subsequently used as an infirmary for the troops stationed at Millbay and Frankfort Barracks."}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0344-2e30be8d9090:d02", "start": 433, "end": 535, "text": "Parts were used as dwellings, but Friary Court was thenceforth never considered a fashionable address."}, "D3S7": {"document_number": 3, "doc_id": "ramdocs-0344-2e30be8d9090:d02", "start": 536, "end": 592, "text": "By 1890 all had disappeared and the bulk of the site was"}}, "candidates": [{"candidate_id": "C0", "answer": "1566", "card_ids": ["ramdocs-0344-2e30be8d9090:d00:c0"]}, {"candidate_id": "C1", "answer": "8 October 1680", "card_ids": ["ramdocs-0344-2e30be8d9090:d01:c0"]}], "original_cards": [{"doc_id": "ramdocs-0344-2e30be8d9090:d00", "card_id": "ramdocs-0344-2e30be8d9090:d00:c0", "entity": "John Sparke", "scope": "death date", "claim": "John Sparke died in 1566.", "answer": "1566", "quote": "John Sparke (died 1566) John Sparke (died 1566) was an English politician who sat in the House of Commons in 1554. Sparke was originally from Nantwich, Cheshire and settled at Plympton St. Maurice. He was collector of the subsidy for Plympton Erle in 1523. In 1554, he was elected Member of Parliament for Plympton Erle. He was mayor of Plympton Erle later in the same year. Sparke died in 1566 and was buried in the church of Plympton St Maurice on 11 July 1566.", "original_document_number": 1}, {"doc_id": "ramdocs-0344-2e30be8d9090:d01", "card_id": "ramdocs-0344-2e30be8d9090:d01:c0", "entity": "John Sparke", "scope": "death date", "claim": "John Sparke died on 8 October 1680.", "answer": "8 October 1680", "quote": "John Sparke (died 1680) John Sparke (1636 - 8 October 1680) of the Friary, in the parish of St Jude, Plymouth, Devon, was an English landowner and politician who sat in the House of Commons from 1677 to 1680.", "original_document_number": 2}], "initial_answers": ["1566", "8 October 1680"]}

